//! "Did this file come back changed?", answered for a `.3mf` a slicer has had. Desktop only
//! (feature `desktop`).
//!
//! **Neither a whole-file hash nor mtime is a valid answer**, and both were measured failing:
//!
//! * All four in-place savers produce a different container hash for byte-identical content.
//!   Anycubic, Bambu and Orca because they write wall-clock ZIP timestamps; PrusaSlicer because
//!   it stamps `; generated by PrusaSlicer 2.9.6 on ... at HH:MM:SS UTC` into the *payload* of
//!   `Metadata/Slic3r_PE.config`. Only PrusaSlicer's reason survives a hash of the decompressed
//!   entries, which is why exactly one exclusion is needed here and why the other three need none.
//! * mtime fails in both directions: the four in-place savers skip the write entirely when
//!   nothing is dirty, and Cura's re-save of unchanged content moved it. It is a *hint* about when
//!   to bother hashing, never an answer.
//!
//! So the hash is over the decompressed entries, and it ignores local and central headers,
//! timestamps, the compression method and entry order.
//!
//! **Memory.** Every entry except the (small) PrusaSlicer config streams through the hasher in
//! chunks, so the peak is one chunk rather than the largest entry. The config is held whole
//! because its first line decides what the hashed bytes are.

use std::collections::BTreeMap;
use std::fs::File;
use std::io::{ErrorKind, Read};
use std::path::Path;
use std::sync::LazyLock;

use regex::Regex;
use sha2::{Digest, Sha256};

use super::chunks::ChunkSource;
use super::zip::{OpenZip, ZipChunkOptions, ZipEntry, decode_utf8, open_zip};
use crate::error::Result;

/// Read size for the non-ZIP path, which streams rather than allocating the file.
const READ_CHUNK_BYTES: usize = 1 << 20;

const SLIC3R_CONFIG: &str = "Metadata/Slic3r_PE.config";

/// The line PrusaSlicer restamps on every save, measured as
/// `; generated by PrusaSlicer 2.9.6 on 2026-08-28 at 09:27:30 UTC`.
///
/// Only ever tested against the part's **first line**, which is where the anchoring actually comes
/// from: [`hashable_bytes`] slices the line off before matching, so `^` and `$` here are about the
/// shape of that one line and not about finding it. `$` earns its place: it is what keeps the
/// pattern from being "any leading comment". The rest of `Slic3r_PE.config` is `; key = value`
/// comment lines that must keep counting. Erring towards *not* excluding is the safe direction:
/// the cost is a spurious "this changed", never a missed one. (`.` is spelled out because a
/// JavaScript `.` stops at `\r`, ` ` and ` ` as well as `\n`.)
static GENERATED_ON: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r"^; generated by [^\n\r  ]* at [^\n\r  ]*UTC$").expect("a valid pattern")
});

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct EntryDiff {
    pub added: Vec<String>,
    pub removed: Vec<String>,
    pub changed: Vec<String>,
}

/// SHA-256 (lowercase hex) over, for each entry in **name order**: the entry name, then the
/// entry's **decompressed** bytes, with the generated-on line of `Metadata/Slic3r_PE.config`
/// excluded.
///
/// For a file whose **central directory does not parse** (an `.stl`, an `.obj`, a `.3mf`
/// truncated mid-write) it is a plain SHA-256 of the file's bytes.
///
/// The fallback is keyed on that parse and nothing else, which is narrower than "not a ZIP" and
/// narrower than "mid-write". A file whose directory parses but whose payload does not (a
/// half-flushed entry behind an intact directory, an unsupported compression method) **fails**
/// rather than falling back, and so does a file that cannot be read at all. The settle window is
/// what that case is for: an error there means "not settled yet", and turning it into a plausible
/// hash of half a file would defeat exactly that.
///
/// Name and content are length-framed rather than simply concatenated. Without framing an archive
/// holding `{a: "bc"}` hashes identically to one holding `{ab: "c"}`, which is a silent
/// "nothing changed" on a file where everything did.
pub fn entry_hash(path: &Path) -> Result<String> {
    let Some(zip) = open_readable_zip(path) else {
        return Ok(hex(hash_file_bytes(path)?));
    };
    let mut entries: Vec<&ZipEntry> = zip.entries().iter().collect();
    // JavaScript compares strings by UTF-16 code unit, and that order is what the hash was
    // defined over.
    entries.sort_by(|a, b| a.name.encode_utf16().cmp(b.name.encode_utf16()));

    let mut hash = Sha256::new();
    for entry in entries {
        framed(&mut hash, entry.name.as_bytes());
        if entry.name == SLIC3R_CONFIG {
            let bytes = zip.read(entry)?;
            framed(&mut hash, hashable_bytes(&entry.name, &bytes));
        } else {
            // The frame carries the declared length, which the reader proves equal to the real
            // one: an entry that does not yield it is an error and the hash is discarded.
            hash.update(entry.uncompressed_size.to_le_bytes());
            feed_entry(&zip, entry, &mut hash)?;
        }
    }
    Ok(hex(hash.finalize().into()))
}

/// Which entries were added, removed, or changed between two files, by name and over decompressed
/// content, with the same generated-on exclusion [`entry_hash`] applies.
///
/// It reports **that** an entry changed, never which setting inside it changed. A slicer's
/// `project_settings.config` is thousands of keys and a round trip rewrites an unknowable number of
/// them; naming one would be an assertion about a file this code has not read.
///
/// A file that is not a readable ZIP is treated as a one-entry archive under its own basename, so
/// an `.stl` that came back changed reports `changed: ["cube.stl"]` rather than nothing at all.
pub fn entry_diff(a: &Path, b: &Path) -> Result<EntryDiff> {
    Ok(diff_digests(&entry_digests(a)?, &entry_digests(b)?))
}

/// The same diff, between two digest maps rather than two paths.
///
/// It exists because **the file a round trip is diffed against is usually gone by the time the
/// diff is wanted.** Four of the five slicers save back over the file they were handed, so the
/// launched bytes no longer exist anywhere: the launch record keeps [`entry_digests`] of the file
/// as it was launched, and this is what turns that record plus the returning file into the diff
/// [`entry_diff`] would have produced had both still been on disk.
pub fn diff_digests(
    before: &BTreeMap<String, String>,
    after: &BTreeMap<String, String>,
) -> EntryDiff {
    let mut diff = EntryDiff::default();
    for (name, digest) in before {
        match after.get(name) {
            None => diff.removed.push(name.clone()),
            Some(other) if other != digest => diff.changed.push(name.clone()),
            Some(_) => {}
        }
    }
    for name in after.keys() {
        if !before.contains_key(name) {
            diff.added.push(name.clone());
        }
    }
    for names in [&mut diff.added, &mut diff.removed, &mut diff.changed] {
        names.sort_by(|a, b| a.encode_utf16().cmp(b.encode_utf16()));
    }
    diff
}

/// One digest per entry, keyed by name: the itemised form of [`entry_hash`].
///
/// The non-ZIP fallback is a single entry under the file's own basename. **It disagrees with
/// [`entry_hash`] on an archive holding two entries of the same name**: `entry_hash` frames and
/// hashes every record it finds, while a map keeps the last, which is what a reader extracting the
/// archive would also end up with. No 3MF writer emits duplicate names, so this is a stated limit
/// rather than a bug with a reproduction, and the failure it produces is a diff that says less
/// than it might, never one that says something false.
pub fn entry_digests(path: &Path) -> Result<BTreeMap<String, String>> {
    let mut digests = BTreeMap::new();
    let Some(zip) = open_readable_zip(path) else {
        let name = path
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_default();
        digests.insert(name, hex(hash_file_bytes(path)?));
        return Ok(digests);
    };
    for entry in zip.entries() {
        let mut hash = Sha256::new();
        if entry.name == SLIC3R_CONFIG {
            let bytes = zip.read(entry)?;
            hash.update(hashable_bytes(&entry.name, &bytes));
        } else {
            feed_entry(&zip, entry, &mut hash)?;
        }
        // Last one wins on a duplicated name; nothing generates them and the map cannot hold both.
        digests.insert(entry.name.clone(), hex(hash.finalize().into()));
    }
    Ok(digests)
}

/// Streams one entry's decompressed bytes into the hash.
fn feed_entry(zip: &OpenZip, entry: &ZipEntry, hash: &mut Sha256) -> Result<()> {
    let mut chunks = zip.read_chunks(
        entry,
        ZipChunkOptions {
            max_chunk_bytes: Some(READ_CHUNK_BYTES),
        },
    )?;
    while let Some(chunk) = chunks.pull_chunk()? {
        hash.update(chunk);
    }
    Ok(())
}

/// The bytes of one entry as they count towards a hash: everything, except the leading
/// generated-on line of `Metadata/Slic3r_PE.config`.
///
/// Done on the bytes rather than on decoded text, so an entry that is not valid UTF-8 is never
/// round-tripped through a decoder that would replace what it could not read.
fn hashable_bytes<'a>(name: &str, bytes: &'a [u8]) -> &'a [u8] {
    if name != SLIC3R_CONFIG {
        return bytes;
    }
    let newline = bytes.iter().position(|&byte| byte == b'\n');
    let end = newline.unwrap_or(bytes.len());
    let first = decode_utf8(&bytes[..end]);
    let first = first.strip_suffix('\r').unwrap_or(&first);
    if !GENERATED_ON.is_match(first) {
        return bytes;
    }
    match newline {
        Some(at) => &bytes[at + 1..],
        None => &bytes[..0],
    }
}

/// An 8-byte little-endian length before the bytes it describes, so the boundary between an
/// entry's name and its content is part of the hash rather than something the reader has to
/// guess.
fn framed(hash: &mut Sha256, bytes: &[u8]) {
    hash.update((bytes.len() as u64).to_le_bytes());
    hash.update(bytes);
}

/// `None` when the path is not a readable ZIP, which is the plain-SHA-256 case.
fn open_readable_zip(path: &Path) -> Option<OpenZip> {
    open_zip(path).ok()
}

fn hash_file_bytes(path: &Path) -> Result<[u8; 32]> {
    let mut file = File::open(path)?;
    let mut hash = Sha256::new();
    let mut buffer = vec![0u8; READ_CHUNK_BYTES];
    loop {
        match file.read(&mut buffer) {
            Ok(0) => break,
            Ok(n) => hash.update(&buffer[..n]),
            Err(error) if error.kind() == ErrorKind::Interrupted => {}
            Err(error) => return Err(error.into()),
        }
    }
    Ok(hash.finalize().into())
}

fn hex(digest: [u8; 32]) -> String {
    use std::fmt::Write;
    digest
        .iter()
        .fold(String::with_capacity(64), |mut out, byte| {
            let _ = write!(out, "{byte:02x}");
            out
        })
}
